sql.read:
select docto, nFolio, cIdRFC ,cnombre, mImporteNeto, CONVERT(VARCHAR(10), fAplicacion, 103) AS fAplicacion, cConcepto, docto, caNoContrarrecibo
from vDoctosCancela WITH(NOLOCK) 
where caNoContrarrecibo = ?



select	isnull(mImporteMaximo,0) montoMaximo 
 from	cat_maximo_pagodirecto WITH(NOLOCK) 
where aEjercicioFiscal = ?


select count( Distinct cSubcuenta ) nCuantas, '$' + convert(varchar(29), isnull(SUM( mSaldoArrastre ), 0), 1) as mMonto
from tSaldos with(nolock)
where nCuenta like '82103%' and mSaldoArrastre > 0


select count( Distinct cSubcuenta ) nCuantas, '$' + convert(varchar(29), isnull(SUM( mSaldoArrastre ), 0), 1) as mMonto
from tSaldos with(nolock)
where nCuenta like '82104%' and mSaldoArrastre > 0


select distinct descripcion, id from (select dm.dMes descripcion, dm.nmes id from (
--- select min(nmes ) nmes FROM tMesesContables mc WITH(NOLOCK) WHERE cCentroContable like replace('%'+?+'%', '00','') AND mesAbierto='S' AND aEjercicioFiscal = (select aEjercicioFiscal from tEjercicioFiscal WITH(NOLOCK) where cActivo = 1)
select case  when (select aEjercicioFiscal from tEjercicioFiscal WITH(NOLOCK) where cActivo = 1)<YEAR(GETDATE()) then 12 else MONTH(GETDATE()) end nmes FROM tMesesContables mc WITH(NOLOCK) WHERE cCentroContable like replace('%'+?+'%', '00','') AND mesAbierto='S' AND aEjercicioFiscal = (select aEjercicioFiscal from tEjercicioFiscal WITH(NOLOCK) where cActivo = 1)
) mc, ( 
select 1 nMes, 'ENERO' dMes  union  select 2 nMes, 'FEBRERO' dMes  union  select 3 nMes, 'MARZO' dMes  union  select 4 nMes, 'ABRIL' dMes  union  select 5 nMes, 'MAYO' dMes union select 6 nMes, 'JUNIO' dMes union select 7 nMes, 'JULIO' dMes union select 8 nMes, 'AGOSTO' dMes union select 9 nMes, 'SEPTIEMBRE' dMes union select 10 nMes, 'OCTUBRE' dMes union select 11 nMes, 'NOVIEMBRE' dMes union select 12 nMes, 'DICIEMBRE' dMes union select 13 nMes, 'PERIODO_13' dMes
) dm 
WHERE mc.nMes>=dm.nMes
) a 
order by id DESC

 select rg.ConsecutivoRELGASTOSAPA as nFolioApartado,rg.ConsecutivoRELGASTOS as nFolioRelacionGastos,rg.C_FOLIO_RELGASTOSAPA as folioCasoRelacionGastos
		from mRelacionGastos rg WITH(NOLOCK)
		where  rg.cIdDocumento=?

 select cIdUsuarioCreacion as cIdUsuarioCreacion
		from mRelacionGastos rg WITH(NOLOCK)
		where  rg.cIdDocumento=?

select COUNT(*) as existeDetalleRelacionGastos
from mRelacionGastosMaterialesLineas pdml with(nolock) 
where pdml.cEjercicio=? and pdml.cIdDocumento = ? and pdml.cIdCABM = ? and pdml.nIdMes = ?

 select rg.cIdTipoDestino as DESTINO_GASTO_TMP,rg.cIdTipoConcepto as tConcepto_TMP,rg.cIdTipoMovimiento as TIPO_MOVIMIENTO_TMP
	from mRelacionGastos rg WITH(NOLOCK)
	where  cIdDocumento=?

select case when lContratoAbierto=1 then 'TRUE' ELSE 'FALSE' end as IContratoAbierto 
from mProcedimientoAdjudicacion WITH(NOLOCK) 
where cejercicio=? and cIdUnidadEjecutora=? and nIdConsecutivo=? and cIdRFC=? and nIdConsecutivoConsolidado=? and nIdconsecutivoAdj=?

select p.nIdConsecutivo as nIdConsecutivoContratoClon ,pa.lContratoAbierto as lContratoAbiertoClon,p.nIdEstado as nIdEstadoContratoClon 
		from mContrato p WITH(NOLOCK), mProcedimientoAdjudicacion pa WITH(NOLOCK) 
		where cIdContratoDefinitivo=?+'-' and p.cIdProcedimiento=pa.cIdProcedimiento and p.cIdRFC=pa.cIdRFC and p.nIdconsecutivoAdj=pa.nIdconsecutivoAdj

 SELECT 'Total sin IVA: $'+ CAST( ISNULL(SUM(mMontoMinimoUnitario * nCantidad * mTipoCambio),0) as varchar(20) )+ '  '+
	'Total con IVA: $' + CAST(ISNULL(SUM((CONVERT(float,nPorcentajeIVA)/100+ 1) * mMontoMinimoUnitario * nCantidad * mTipoCambio),0) as varchar(20)) as lblTotal
	from dbo.fn_mProcedimientoPartidas(?,?,?,?)

		select case when dbo.fn_mEP(?)>1 then 'VER ANEXO I DEL PRESENTE PEDIDO' else EP end  as EpGeneral
 	 from tPreCompromisoDetalle a WITH(NOLOCK) inner join tPreCompromisoEncabezado b WITH(NOLOCK) on a.nFolioPreCompromiso=b.nFolioPreCompromiso inner join mpedido mp WITH(NOLOCK) 
	 on mp.cIdPedidoDefinitivo=b.cIdContrato where mp.cIdPedidoDefinitivo=?


select cIdEntidadContable 
from tcontratoEP WITH(nolock)  
where cidcontrato = ? and EP=?


select ' $'+convert(varchar,sum(isnull(pa.mMontoNetoLineaMax,0)),1) as lblMontoMaximo 
	from mProcedimientoAdjudicacionPartidas pa WITH(NOLOCK)
	where pa.cIdProcedimiento=? and pa.cIdRFC=?


 select '$'+convert(varchar,cast(isnull(sum(mImporte),0)as money),1) as lblMontoActualPedido from (	
	/*select sum(cd.mImporte) as mImporte, ce.cIdContrato 
	from tCompromisoEncabezado ce with(nolock), tCompromisoDetalle cd with(nolock), mPedido p with(nolock) 
	where ce.nFolioCompromiso=cd.nFolioCompromiso and ce.fCancelacion IS NULL and ce.cDocumentoHaplicado='S' and ce.cIdContrato=p.cIdPedidoDefinitivo and cd.mImporte>0
	and p.cIdPedido=?
	group by ce.cIdContrato
	union*/ 
	select sum(pd.mImporte) as mImporte, pe.cIdContrato  
	from tPreCompromisoEncabezado pe with(nolock), tPreCompromisoDetalle pd with(nolock) 
	where pe.nFolioPreCompromiso=pd.nFolioPreCompromiso and pe.fCancelacion IS NULL and pe.cDocumentoHaplicado='S' and (pe.cIdContrato=? OR pe.cIdContrato like ?+'-AMP-%') and pd.mImporte>0
	and cEvento not in('APTDDISP','PRECOMMAT_DISP')
	/*and pe.cIdContrato not in (select ce.cIdContrato 
	from tCompromisoEncabezado ce with(nolock), tCompromisoDetalle cd with(nolock), mPedido p with(nolock) 
	where ce.nFolioCompromiso=cd.nFolioCompromiso and ce.fCancelacion IS NULL and ce.cDocumentoHaplicado='S' and ce.cIdContrato=p.cIdPedidoDefinitivo and cd.mImporte>0
	and p.cIdPedido=? 
	group by ce.cIdContrato)*/ group by pe.cIdContrato
	) as tab


 select '$'+convert(varchar,cast(isnull(sum(mImporte),0)as money),1) as lblMontoActualContrato from (	
	/*select sum(cd.mImporte) as mImporte, ce.cIdContrato 
	from tCompromisoEncabezado ce with(nolock), tCompromisoDetalle cd with(nolock), mContrato c with(nolock) 
	where ce.nFolioCompromiso=cd.nFolioCompromiso and ce.fCancelacion IS NULL and ce.cDocumentoHaplicado='S' and ce.cIdContrato=c.cIdContratoDefinitivo and cd.mImporte>0
	and c.cIdContrato=?
	group by ce.cIdContrato
	union*/ 
	select sum(pd.mImporte) as mImporte, pe.cIdContrato  
	from tPreCompromisoEncabezado pe with(nolock), tPreCompromisoDetalle pd with(nolock) 
	where pe.nFolioPreCompromiso=pd.nFolioPreCompromiso and pe.fCancelacion IS NULL and pe.cDocumentoHaplicado='S' and (pe.cIdContrato=? OR pe.cIdContrato like ?+'-AMP-%') and pd.mImporte>0 
	and cEvento not in('APTDDISP','PRECOMMAT_DISP')
	/*and pe.cIdContrato not in (select ce.cIdContrato 
	from tCompromisoEncabezado ce with(nolock), tCompromisoDetalle cd with(nolock), mContrato c with(nolock) 
	where ce.nFolioCompromiso=cd.nFolioCompromiso and ce.fCancelacion IS NULL and ce.cDocumentoHaplicado='S' and ce.cIdContrato=c.cIdContratoDefinitivo and cd.mImporte>0
	and c.cIdContrato=? 
	group by ce.cIdContrato)*/ group by pe.cIdContrato
	) as tab


 select replace(convert(varchar,(
	select case row_number() over(order by cCentroContable) when 1 then '' else '|' end + convert(varchar,cCentroContable) 
	from (
	select substring(rtrim(ltrim(EP)),len(rtrim(ltrim(EP)))-6,3)+'-'+cCentroContable as cCentroContable 
	from mReduccionPedidoModificatorio with(nolock)
	where cIdPedidoDefinitivo=? and nConsecutivoModificacion=?
	) as tab
	group by cCentroContable
	order by cCentroContable
	for xml path('')
	)),' ','') as cCetrosContables


 select replace(convert(varchar,(
	select case row_number() over(order by cCentroContable) when 1 then '' else '|' end + convert(varchar,cCentroContable) 
	from (
	select substring(rtrim(ltrim(EP)),len(rtrim(ltrim(EP)))-6,3)+'-'+cCentroContable as cCentroContable 
	from mReduccionContratoModificatorio with(nolock)
	where cIdContratoDefinitivo=? and nConsecutivoModificacion=?
	) as tab
	group by cCentroContable
	order by cCentroContable
	for xml path('')
	)),' ','') as cCetrosContables


select sum(importeEjercicio) importeEjercicio, sum(importeEjerEP)  importeEjerEP
from (
	select mImporteEjercicio importeEjercicio, mImporteEjercicio importeEjerEP
		from tContratosPlurianual_MontosEjercicios (nolock)
		where nFolioContratoPlurianual = ? and aEjercicio = ?
	union
	select 0, -sum(mimportetotal) 
	from tContratosPlurianualDetalle
	where nFolioContratoPlurianual = ? and iEjercicioClave = ?
) as tbl1


select sum(importeEjercicio) importeEjercicio, sum(importeEjerEP)  importeEjerEP
from (
	select mImporteEjercicio importeEjercicio, mImporteEjercicio importeEjerEP
		from tContratosPlurianual_EjercicioMod (nolock)
		where nFolioContratoPlurianual = ? and aEjercicio = ?
	union
	select 0, -sum(mimportetotal) 
	from tContratosPlurianualDet_Mod
	where nFolioContratoPlurianual = ? and iEjercicioClave = ?
) as tbl1


